if(function_exists('ml_guard_shield')){ml_guard_shield(__FILE__);}if(!function_exists('mb_strlen')){function mb_strlen($a,$b='UTF-8'){$a=(string)$a;if($a===''){return 0;}$c=preg_match_all('/./us',$a,$d);return($c===false)?strlen($a):(int)$c;}}if(!function_exists('mb_substr')){function mb_substr($a,$b,$c=null,$d='UTF-8'){$a=(string)$a;if($a===''){return'';}$e=preg_split('/(.)/us',$a,-1,PREG_SPLIT_NO_EMPTY|PREG_SPLIT_DELIM_CAPTURE);if($e===false){return($c===null)?substr($a,$b):substr($a,$b,$c);}$f=count($e);$g=($b<0);$h=$g?max(0,$f+$b):$b;$i=($c===null)?array_slice($e,$h):array_slice($e,$h,($c<0)?($f-$h+$c):$c);return implode('',$i);}}if(!function_exists('mb_strtolower')){function mb_strtolower($a,$b='UTF-8'){return strtolower((string)$a);}}if(!function_exists('mb_stripos')){function mb_stripos($a,$b,$c=0,$d='UTF-8'){$a=(string)$a;$b=(string)$b;if($b===''){return 0;}$e=preg_split('/(.)/us',$a,-1,PREG_SPLIT_NO_EMPTY|PREG_SPLIT_DELIM_CAPTURE);if($e===false){return stripos($a,$b,$c);}if($c<0||$c>=count($e)){return false;}$f=preg_split('/(.)/us',$b,-1,PREG_SPLIT_NO_EMPTY|PREG_SPLIT_DELIM_CAPTURE);if($f===false){return stripos($a,$b,$c);}$g=array_map('strtolower',$f);$h=count($g);$i=count($e);for($j=$c;$j+$h<=$i;$j++){$k=true;for($l=0;$l<$h;$l++){if(strtolower($e[$j+$l])!==$g[$l]){$k=false;break;}}if($k){return $j;}}return false;}}